local config = {
  ui_story_5048_50480101_1_dialog_content = "<color=#e8d9bb>Cuit, cuit, teriak...</color>",
  ui_story_5048_50480101_2_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay - Distrik Barat</color>",
  ui_story_5048_50480101_3_dialog_content = "Yang mulia?",
  ui_story_5048_50480101_4_dialog_content = "<size=50>Putri Dantang!</size>",
  ui_story_5048_50480101_5_dialog_content = "Hmm?",
  ui_story_5048_50480101_6_dialog_content = "Mata Anda terpejam begitu erat, Yang Mulia, dan Anda begitu diam... Mohon beritahu, apakah Anda merasa tidak nyaman?",
  ui_story_5048_50480101_7_dialog_content = "Maaf telah membuatmu khawatir, Jiu, aku hanya fokus pada irama piano yang sangat indah ini.",
  ui_story_5048_50480101_8_dialog_content = "Dengarkan—suara ini lembut seperti air, tetapi juga memiliki keanggunan yang megah. Ini sangat berbeda dari instrumen Longzhou. Sungguh nikmat bagi telinga.",
  ui_story_5048_50480101_9_dialog_content = "Jika ada kesempatan di masa depan, aku ingin bermain bersama seorang pianis, dan mungkin kamu bisa menampilkan tarian pedang di sisiku...",
  ui_story_5048_50480101_10_dialog_content = "Anda seorang visioner sejati, Yang Mulia.",
  ui_story_5048_50480101_11_dialog_content = "Tidakkah kamu merasa aneh? Mereka bilang <color=#FFB400>Twin Pavilions Bay</color> menikmati banyak hujan dan iklim yang menyenangkan selama musim ini... Namun, akhir-akhir ini cuaca sangat panas dan kering.",
  ui_story_5048_50480101_12_dialog_content = "Apakah ini kunjungan pertama Anda ke Twin Pavilions Bay?",
  ui_story_5048_50480101_13_dialog_content = "Cuaca di Twin Pavilions Bay tahun ini agak tidak biasa. Kami semua menantikan angin sepoi-sepoi laut yang sejuk dan hujan yang baik.",
  ui_story_5048_50480101_14_dialog_content = "Ups, maaf, aku sedikit menyimpang dari topik. Ini pesananmu, semua hidangan yang kamu pesan.",
  ui_story_5048_50480101_15_dialog_content = "Kami harap pemandangan indah ini dapat menghilangkan ketidaknyamanan akibat cuaca panas. Selamat menikmati makanan Anda.",
  ui_story_5048_50480101_16_dialog_content = "Seperti yang diharapkan dari restoran paling terkenal di Twin Pavilions Bay—pelayanan di sini benar-benar luar biasa.",
  ui_story_5048_50480101_17_dialog_content = "Yang Mulia, ada satu hal yang masih belum saya mengerti sepenuhnya.",
  ui_story_5048_50480101_18_dialog_content = "Little Longzhou di sebelah timur kota ini memiliki banyak restoran yang menyajikan hidangan bergaya Longzhou yang sudah sangat akrab bagi Anda.",
  ui_story_5048_50480101_19_dialog_content = "Lalu mengapa Anda terus-menerus datang ke restoran Astra di sebelah barat kota ini saat lapar melanda?",
  ui_story_5048_50480101_20_dialog_content = "Langkah pertama dalam diplomasi adalah memahami adat istiadat dan tradisi setempat, dan langkah pertama untuk memperoleh pemahaman tersebut adalah...",
  ui_story_5048_50480101_21_dialog_content = "Tentu saja, memulai dengan makanan lokal adalah cara tercepat.",
  ui_story_5048_50480101_22_dialog_content = "Anda benar sekali, Yang Mulia.",
  ui_story_5048_50480101_23_dialog_content = "Hmm? Maafkan kelalaianku, seharusnya aku sudah meminta sumpit disiapkan untuk meja kita. Aku akan memanggil pelayannya.",
  ui_story_5048_50480101_24_dialog_content = "Lihat, Jiu, pisau dan garpu ini adalah alat makan di sini.",
  ui_story_5048_50480101_25_dialog_content = "Pisau dan garpu... sebagai alat makan? Mengapa mereka terasa lebih seperti senjata pribadi bagi saya?",
  ui_story_5048_50480101_26_dialog_content = "Haha. Aku tahu kamu harus berlatih bela diri sepanjang hari, tapi kamu benar-benar perlu membaca beberapa buku yang sudah kuberikan saat kamu punya waktu. Pelajari sesuatu tentang budaya di sini.",
  ui_story_5048_50480101_27_dialog_content = "Ya…",
  ui_story_5048_50480101_28_dialog_content = "Nah, jika alat makan sudah siap, mengapa Anda belum makan, Yang Mulia?",
  ui_story_5048_50480101_29_dialog_content = "Aku hanya penasaran bagaimana kamu akan makan dengan topeng itu?",
  ui_story_5048_50480101_30_dialog_content = "Yang Mulia, tentu saja saya akan melayani Anda saat Anda makan.",
  ui_story_5048_50480101_31_dialog_content = "Masih belum terbiasa menunjukkan wajahmu di depan umum?",
  ui_story_5048_50480101_32_dialog_content = "Saya khawatir penampilan saya mungkin menyinggung mata Yang Mulia, sehingga Yang Mulia tidak bisa makan...",
  ui_story_5048_50480101_33_dialog_content = "Baiklah, tapi bukankah sudah kubilang bahwa bahkan kata \"cantik\" itu sendiri tidak bisa menggambarkan penampilanmu dengan adil? Mengapa kamu masih tidak percaya padaku?",
  ui_story_5048_50480101_34_dialog_content = "Oh, haruskah aku memakan semua makanan lezat ini sendirian? Apakah kamu begitu ingin melihatku menderita sakit pencernaan?",
  ui_story_5048_50480101_35_dialog_content = "Aku tak akan pernah memimpikan hal seperti itu!",
  ui_story_5048_50480101_36_dialog_content = "Ehem... Ayo, coba saja.",
  ui_story_5048_50480101_37_dialog_content = "... Ya, Yang Mulia!",
  ui_story_5048_50480101_38_dialog_content = "<color=#e8d9bb>Jiu dengan hati-hati mencoba semua hidangan.</color>",
  ui_story_5048_50480101_39_dialog_content = "Bagaimana menurutmu?",
  ui_story_5048_50480101_40_dialog_content = "Yang Mulia, saya telah mencicipi semua makanan, dan Anda bisa yakin bahwa makanan tersebut tidak mengandung racun.",
  ui_story_5048_50480101_41_dialog_content = "Aku ingin tahu pendapatmu tentang rasanya. Apakah sesuai dengan seleramu?",
  ui_story_5048_50480101_42_dialog_content = "Itu... aku tidak memperhatikan.",
  ui_story_5048_50480101_43_dialog_content = "Kali berikutnya, nikmati setiap suapan dengan saksama bersamaku. Pastikan jangan buang-buang makanan langka ini lagi.",
  ui_story_5048_50480101_44_dialog_content = "Saya mengerti. Yang Mulia tidak bermaksud agar saya mencoba makanan untuk menguji racun...",
  ui_story_5048_50480101_45_dialog_content = "Tentu saja. Bagaimana lagi kamu bisa menikmati makanan lezat ini bersamaku?",
  ui_story_5048_50480101_46_dialog_content = "Yang Mulia, saya mohon untuk menunggu sebentar!",
  ui_story_5048_50480101_47_dialog_content = "Setelah melihat lebih dekat barusan, aku menyadari sesuatu...",
  ui_story_5048_50480101_48_dialog_content = "Isian Pizza Batu Bata ini sebenarnya belum dipanggang ke dalam kue...",
  ui_story_5048_50480101_49_dialog_content = "Beef Roayl ini tidak dimasak dengan benar! Lihat saja semua aliran darah yang mengalir di dalamnya!",
  ui_story_5048_50480101_50_dialog_content = "Dan Salad Musiman dengan Glaze Madu ini jelas mengandung sayuran mentah! Mereka sama sekali tidak dimasak!",
  ui_story_5048_50480101_51_dialog_content = "Apakah hidangan yang dibuat sembarangan ini benar-benar bisa disebut sebagai makanan lezat Twin Pavilions Bay?",
  ui_story_5048_50480101_52_dialog_content = "Tenanglah, Jiu—jangan terlalu tidak sabar. Seperti pepatah, lingkungan berperan besar dalam perkembangan seseorang.",
  ui_story_5048_50480101_53_dialog_content = "Ingatlah, perbedaan regional dalam diet ada di antara berbagai kerajaan vasal Longzhou, dan perbedaan ini bahkan lebih jelas di Astra, karena dipisahkan dari kita oleh samudra yang luas.",
  ui_story_5048_50480101_54_dialog_content = "Belajar menghargai masakan dari berbagai daerah adalah salah satu pelajaran yang harus kita pelajari dalam perjalanan kita mengelilingi dunia.",
  ui_story_5048_50480101_55_dialog_content = "Pizza Stone Kiln ini bukan salah satu pie Longzhou kami.",
  ui_story_5048_50480101_56_dialog_content = "Pizza ini khususnya dipanggang dalam tungku batu bersuhu tinggi, dan seharusnya memiliki kerak yang renyah, isian yang melimpah, serta keju yang segar dan harum.",
  ui_story_5048_50480101_57_dialog_content = "Bagaimana dengan Beef Royal ini?",
  ui_story_5048_50480101_58_dialog_content = "Di Longzhou, kami cenderung menggoreng daging hingga lembut dan empuk, dan kami memberi rasa dengan berbagai bumbu.",
  ui_story_5048_50480101_59_dialog_content = "Namun, Beef Royal ini berusaha untuk mempertahankan rasa asli dari bahan-bahan sebanyak mungkin. Dagingnya segar, lembut, dan juicy, serta meleleh di mulut Anda...",
  ui_story_5048_50480101_60_dialog_content = "Jika kualitas daging sapi tidak dikendalikan dengan ketat sejak tahap pembiakan, rasa seperti ini pasti tidak mungkin dihasilkan.",
  ui_story_5048_50480101_61_dialog_content = "Mereka bilang bahwa di masa lalu, hanya Lumo Noble yang bergengsi saja yang diizinkan untuk mencicipi hidangan ini.",
  ui_story_5048_50480101_62_dialog_content = "Saya mengerti... Lalu apa cerita di balik Salad Musiman Berlapis Madu ini?",
  ui_story_5048_50480101_63_dialog_content = "Sayuran ini memang sangat segar dan hadir dalam berbagai macam jenis. Bahkan, banyak di antaranya yang tidak ditanam secara lokal.",
  ui_story_5048_50480101_64_dialog_content = "Sebuah restoran yang dapat menyediakan sayuran segar untuk pengunjung dari tempat lain di tengah panas yang menyengat...",
  ui_story_5048_50480101_65_dialog_content = "Baik itu menjaga kepercayaan baik atau menyimpan dan melestarikan makanan, segala yang mereka lakukan adalah kelas satu.",
  ui_story_5048_50480101_66_dialog_content = "Masalahnya adalah saus ini terasa terlalu manis untuk selera saya. Seandainya pelanggan bisa memilih saus mereka sendiri.",
  ui_story_5048_50480101_67_dialog_content = "Yang Mulia, meskipun baru-baru ini Anda mengenal kelezatan Astra, Anda sudah memiliki pemahaman yang mendalam tentangnya... Anda memang permata mahkota Kerajaan Ye!",
  ui_story_5048_50480101_68_dialog_content = "Jiu, mengapa akhir-akhir ini kamu begitu sering menyanjungku?",
  ui_story_5048_50480101_69_dialog_content = "Bisakah itu karena kamu belajar beberapa trik dari <color=#FFB400>orang yang pandai bicara</color> di kapal saat dalam perjalanan ke sini?",
  ui_story_5048_50480101_70_dialog_content = "Jika Yang Mulia tidak menyukainya, saya akan berbicara lebih sedikit.",
  ui_story_5048_50480101_71_dialog_content = "Jiu, kamu benar-benar perlu belajar mengenali dan bereaksi terhadap candaan yang menggoda...",
  ui_story_5048_50480101_72_dialog_content = "Hmm?",
  ui_story_5048_50480101_73_dialog_content = "Apa-apaan kau ini?!",
  ui_story_5048_50480101_74_dialog_content = "Ah...",
  ui_story_5048_50480101_75_dialog_content = "Kamu menakuti mereka.",
  ui_story_5048_50480101_76_dialog_content = "Maafkan kekasaran saya.",
  ui_story_5048_50480101_77_dialog_content = "Tapi kamu mengganggu kami berdua di tengah makan. Ada apa?",
  ui_story_5048_50480101_78_dialog_content = "Eh, inilah masalahnya.",
  ui_story_5048_50480101_79_dialog_content = "Bos kami, Pak Ernest, baru saja mendengar umpan balik Anda tentang hidangan kami, dan dia sangat terkejut dengan senang hati.",
  ui_story_5048_50480101_80_dialog_content = "\"Memiliki wawasan yang tepat mengenai masakan lokal kita pada percobaan pertama Anda sungguh luar biasa.\"",
  ui_story_5048_50480101_81_dialog_content = "Bos kami ingin mengundang kalian berdua ke dapur kami dan membahas seni memasak jika kalian memiliki waktu untuk itu.",
  ui_story_5048_50480101_82_dialog_content = "Bisakah Anda berdua memberkati kami dengan kehadiran Anda?",
  ui_story_5048_50480101_83_dialog_content = "Anda terlalu baik, saya hanya memberikan beberapa pendapat jujur yang mungkin tidak konvensional sebelumnya.",
  ui_story_5048_50480101_84_dialog_content = "Sangat murah hati dari pemilik untuk mengundang kita, dan sifat toleransinya benar-benar patut dicontoh. Kami dengan senang hati menerima undangan Anda.",
  ui_story_5048_50480101_85_dialog_content = "Yang Mulia! Kami baru di sini dan belum familiar dengan adat istiadat setempat.",
  ui_story_5048_50480101_86_dialog_content = "Jika kita ceroboh menerima undangan dari orang asing dan menghilang dari pandangan umum, mungkin saja...",
  ui_story_5048_50480101_87_dialog_content = "Jika kamu mengenalku, seharusnya kamu tahu bahwa aku bukan orang yang lemah yang tidak memiliki kekuatan untuk melindungi diri sendiri.",
  ui_story_5048_50480101_88_dialog_content = "Selain itu, bukankah saya ditemani oleh pengawal yang memiliki kemampuan seni bela diri tak tertandingi?",
  ui_story_5048_50480101_89_dialog_content = "Tentu saja, aku akan secara alami di sini untuk melindungimu.",
  ui_story_5048_50480101_90_dialog_content = "Meskipun kita belum sempat membahas seni piano dengan pianis... mendiskusikan makanan lezat dengan seorang gourmet terlebih dahulu juga merupakan kesempatan yang luar biasa.",
  ui_story_5048_50480101_91_dialog_content = "Jadi, saya meminta Anda untuk memimpin jalan, jika itu menyenangkan Anda.",
  ui_story_5048_50480101_92_dialog_content = "Tamu terhormat, silakan ke sini.",
  ui_story_5048_50480101_93_dialog_content = "<color=#e8d9bb>Seri klink dan gemerincing!</color>",
  ui_story_5048_50480101_94_dialog_content = "Oh tidak, apakah mungkin seseorang menjatuhkan piring saat menyajikan? Bos pasti akan marah lagi...",
  ui_story_5048_50480101_95_dialog_content = "A-aku butuh bantuan di sini!",
  ui_story_5048_50480101_96_dialog_content = "Tolong!",
  ui_story_5048_50480101_97_dialog_content = "Hah? Apa itu...",
  ui_story_5048_50480101_98_dialog_content = "Li Tianxian?!",
  ui_story_5048_50480201_1_dialog_content = "<color=#e8d9bb>Beberapa waktu lalu</color>",
  ui_story_5048_50480201_2_dialog_content = "<color=#e8d9bb>Cuit, cuit, teriak...</color>",
  ui_story_5048_50480201_3_dialog_content = "Melon emas menyusut.",
  ui_story_5048_50480201_4_dialog_content = "Tanggal perak tenggelam.",
  ui_story_5048_50480201_5_dialog_content = "Perut kosong keroncongan.",
  ui_story_5048_50480201_6_dialog_content = "Kantong pengemis berdenting!",
  ui_story_5048_50480201_7_dialog_content = "... Mengomel, Mengoceh, bisakah kalian berdua tenang sejenak?",
  ui_story_5048_50480201_8_dialog_content = "Liburan! Liburan!",
  ui_story_5048_50480201_9_dialog_content = "Pulang! Pulang!",
  ui_story_5048_50480201_10_dialog_content = "Jika bisnis tidak segera membaik, darimana kita akan mendapatkan uang untuk melon emas dan kurma perak?",
  ui_story_5048_50480201_11_dialog_content = "Tapi jangan khawatir. Aku menjelajahi dunia, mengembara ke sana kemari. Kapan pun aku pernah membuat kalian berdua kelaparan?",
  ui_story_5048_50480201_12_dialog_content = "Tunggu sebentar lagi...",
  ui_story_5048_50480201_13_dialog_content = "Hmm?",
  ui_story_5048_50480201_14_dialog_content = "Lihat saja, bukankah perubahan takdir kita sudah dekat di tangan?",
  ui_story_5048_50480201_15_dialog_content = "Selamat datang! Pak, apakah Anda makan sendirian?",
  ui_story_5048_50480201_16_dialog_content = "Saya mencari seseorang.",
  ui_story_5048_50480201_17_dialog_content = "Dia di dalam—saya bisa menemukannya sendiri, tidak perlu repot-repot membantu!",
  ui_story_5048_50480201_18_dialog_content = "Oke, Pak.",
  ui_story_5048_50480201_19_dialog_content = "Luar biasa... Di sini sangat luas dan terang, serta jauh lebih sejuk daripada di luar. Sungguh permata kecil yang menakjubkan yang telah kutemukan.",
  ui_story_5048_50480201_20_dialog_content = "Sekarang, saatnya untuk mulai mencari. Biar ku lihat...",
  ui_story_5048_50480201_21_dialog_content = "Yah, batu gagak-gagak itu!",
  ui_story_5048_50480201_22_dialog_content = "Jelas terlihat Anda adalah orang yang kaya raya dan berpangkat tinggi, tetapi apa yang membuat alis Anda berkerut dan wajah Anda muram hari ini?",
  ui_story_5048_50480201_23_dialog_content = "Ada sesuatu yang mengganggumu.",
  ui_story_5048_50480201_24_dialog_content = "Apapun itu, aku tidak merasa ini ada hubungannya denganmu.",
  ui_story_5048_50480201_25_dialog_content = "Oh, benarkah? Tapi bagaimana bisa itu tidak ada hubungannya denganku?",
  ui_story_5048_50480201_26_dialog_content = "Izinkan saya memperkenalkan diri. Saya Li Tianxian, baru saja turun dari feri dari Longzhou.",
  ui_story_5048_50480201_27_dialog_content = "Meskipun saya tidak bisa bicara tentang kemampuan saya sendiri, beberapa orang menganggap saya sebagai seorang pengrajin ulung.",
  ui_story_5048_50480201_28_dialog_content = "Seorang pengrajin, ya? Kamu bukan koki, kebetulan?",
  ui_story_5048_50480201_29_dialog_content = "Tidak, tidak, tidak. Lihat, hidup dan mati ditentukan oleh takdir, kekayaan dan kemuliaan oleh langit. Saya adalah ahli prinsip Yin dan Yang serta teori Lima Unsur—satu dengan tingkat akurasi ramalan minimal sembilan puluh persen yang dijamin.",
  ui_story_5048_50480201_30_dialog_content = "Kerajinan saya dikenal sebagai <color=#FFB400>ramalan</color>.",
  ui_story_5048_50480201_31_dialog_content = "Aku bisa menggambarkan jalannya takdirmu, membimbingmu melewati jerat-jerat nasib dengan aman, dan kadang-kadang... bahkan mengubah masa depan, menentang langit itu sendiri.",
  ui_story_5048_50480201_32_dialog_content = "Apapun kesulitan yang kamu hadapi, serahkan padaku dan aku akan memberikan solusi untukmu.",
  ui_story_5048_50480201_33_dialog_content = "Kepuasan dijamin!",
  ui_story_5048_50480201_34_dialog_content = "Akurasi total, atau uang kembali!",
  ui_story_5048_50480201_35_dialog_content = "Pak, jika Anda tidak di sini untuk makan, tolong jangan mengganggu tamu-tamu terhormat kami dan segera pergi.",
  ui_story_5048_50480201_36_dialog_content = "Sekarang, sekarang, sekarang... Ada waktu dan tempat untuk segalanya, dan saat ini, saya belum selesai berbicara dengan tamu terhormat Anda.",
  ui_story_5048_50480201_37_dialog_content = "Tidak maukah kamu setidaknya memikirkannya?",
  ui_story_5048_50480201_38_dialog_content = "Jika kamu tidak puas, aku akan pergi.",
  ui_story_5048_50480201_39_dialog_content = "Biarkan dia duduk.",
  ui_story_5048_50480201_40_dialog_content = "Tn. Victor...?",
  ui_story_5048_50480201_41_dialog_content = "Jangan khawatir tentang itu, lanjutkan dan kembali ke tugas Anda.",
  ui_story_5048_50480201_42_dialog_content = "Heheh, temanku, kamu harus mencoba lebih menghormati pelangganmu di masa depan.",
  ui_story_5048_50480201_43_dialog_content = "...",
  ui_story_5048_50480201_44_dialog_content = "Pak Victor, sepertinya semua orang yang bekerja di sini mengenal Anda. Anda pasti pelanggan tetap.",
  ui_story_5048_50480201_45_dialog_content = "Ya, bisa dibilang begitu.",
  ui_story_5048_50480201_46_dialog_content = "Terima kasih atas bantuan baikmu tadi!",
  ui_story_5048_50480201_47_dialog_content = "Menemukan jiwa yang baik dan benar seperti Anda merupakan hal yang jarang terjadi saat ini. Oleh karena itu, saya akan memberikan Anda ramalan dengan harga diskon.",
  ui_story_5048_50480201_48_dialog_content = "Jika kekuatanmu memang sehebat yang kamu klaim, aku tidak akan memperlakukanmu secara tidak adil.",
  ui_story_5048_50480201_49_dialog_content = "Sekarang, coba tunjukkan apa yang bisa kamu lakukan.",
  ui_story_5048_50480201_50_dialog_content = "<color=#e8d9bb>Wuuuuuuss!!</color>",
  ui_story_5048_50480201_51_dialog_content = "Yin Tikus di atas, Yang Kerbau di bawah.",
  ui_story_5048_50480201_52_dialog_content = "Pak, ramalan menunjukkan tikus sedang menunggang punggung kerbau.",
  ui_story_5048_50480201_53_dialog_content = "Pergantian Yin dan Yang, konflik universal—semua ketidakharmonisan saling terkait dengan sebab dan akibat.",
  ui_story_5048_50480201_54_dialog_content = "Gambar yang ditampilkan dalam hexagram ini mengungkapkan strategi masa depan Anda untuk mengatasi konflik ini.",
  ui_story_5048_50480201_55_dialog_content = "Hmm? Mari kita dengarkan kalau begitu.",
  ui_story_5048_50480201_56_dialog_content = "Pertama-tama, jika Anda tidak ingin menjadi batu loncatan bagi kesuksesan orang lain, Anda harus lebih berhati-hati terhadap mereka yang ingin mencelakakan Anda.",
  ui_story_5048_50480201_57_dialog_content = "Bagaimana aku bisa tahu siapa yang mencoba menghabisiku?",
  ui_story_5048_50480201_58_dialog_content = "Jangan khawatir, Tuan, karena ramalan ini memiliki arti kedua.",
  ui_story_5048_50480201_59_dialog_content = "Meskipun Anda mungkin bertemu dengan orang-orang yang berkepribadian buruk, Anda akan selalu menerima bantuan dari orang-orang yang saleh di saat bahaya, menemukan jalan baru untuk maju dan mengubah kemalangan menjadi berkah.",
  ui_story_5048_50480201_60_dialog_content = "Yang berbudi luhur, katamu?",
  ui_story_5048_50480201_61_dialog_content = "Maksudnya, pada saat-saat terakhir, seseorang akan datang untuk menyelamatkanmu, dan semua masalahmu akan terselesaikan dengan mudah.",
  ui_story_5048_50480201_62_dialog_content = "Dan kamu akan selalu diberkati keberuntungan sepanjang hidupmu.",
  ui_story_5048_50480201_63_dialog_content = "Ha ha ha! Luar biasa! Saya dengan senang hati akan membayar untuk kata-kata yang penuh berkah seperti itu. Saya harap saya benar-benar akan diberkahi keberuntungan yang baik, seperti yang Anda katakan.",
  ui_story_5048_50480201_64_dialog_content = "Oh, Anda benar-benar jiwa yang baik... Pemberi manfaat mulia saya, mohon terima rasa terima kasih terdalam saya, dan hormat yang lebih dalam lagi dari pelayan rendah hati Anda.",
  ui_story_5048_50480201_65_dialog_content = "Hmph! Kau menganggap dirimu seorang pengrajin, hanya karena tahu cara mengatakan apa yang orang ingin dengar?",
  ui_story_5048_50480201_66_dialog_content = "Dan kenyataan bahwa kamu melakukan semua ini demi sedikit uang membuatmu semakin hina.",
  ui_story_5048_50480201_67_dialog_content = "...",
  ui_story_5048_50480201_68_dialog_content = "Pak, saya tidak memiliki niat buruk pada Anda. Untuk alasan apa Anda merasa perlu menegur saya dengan keras?",
  ui_story_5048_50480201_69_dialog_content = "Kata-kata seperti itu tidak mempengaruhi saya secara pribadi, tetapi jika itu meredupkan suasana hati Anda, tentu saja kerugian Anda lebih besar daripada keuntungan Anda.",
  ui_story_5048_50480201_70_dialog_content = "Apakah makanan hari ini sesuai dengan keinginan Anda?",
  ui_story_5048_50480201_71_dialog_content = "(Omongan dia memang kasar, tapi sepertinya dia tidak bermaksud menyakitiku...)",
  ui_story_5048_50480201_72_dialog_content = "Iya, enak.",
  ui_story_5048_50480201_73_dialog_content = "Bagaimana kamu bisa tahu rasanya jika belum mencoba menggigitnya?",
  ui_story_5048_50480201_74_dialog_content = "Apakah ini yang sebenarnya kamu inginkan dari hidup? Berpura-pura semuanya baik-baik saja dan mengejar kedamaian yang dangkal?",
  ui_story_5048_50480201_75_dialog_content = "Kamu seorang gourmet. Menyebut setiap hidangan di depanmu sebagai lezat adalah awal kehancuran bagi seseorang yang memiliki standar!",
  ui_story_5048_50480201_76_dialog_content = "Ada lebih dari satu standar di dunia ini, dan saya memiliki cara sendiri dalam melihat sesuatu.",
  ui_story_5048_50480201_77_dialog_content = "Hanya menunjukkan kebenaran yang tidak menyenangkan tentang dunia tidak cukup untuk bertahan di dalamnya. Jika kita bahkan tidak bisa mencapai kedamaian yang dangkal, harapan apa yang kita miliki untuk mencapai kedamaian yang sebenarnya?!",
  ui_story_5048_50480201_78_dialog_content = "(Tch... Aku khawatir mungkin ada misteri lain di balik konfrontasi antara kedua orang ini.)",
  ui_story_5048_50480201_79_dialog_content = "Saudara baik, tolong, jangan membuat diri Anda marah seperti ini. Ingat ramalan tadi?",
  ui_story_5048_50480201_80_dialog_content = "Jenis tekanan emosional ini pasti akan memicu api dalam dirimu, yang sangat mudah menyebabkan penurunan kesehatanmu dengan cepat. Jika musuh bebuyutanmu menyerang saat kamu dalam keadaan ini, penyelamatmu tak akan ada di mana-mana, dan tragedi akan mengikuti.",
  ui_story_5048_50480201_81_dialog_content = "Itu sebenarnya masuk akal, Master Li.",
  ui_story_5048_50480201_82_dialog_content = "Kurasa kamu terlalu banyak mendengarkan omong kosong si tukang tipu ini!",
  ui_story_5048_50480201_83_dialog_content = "Oh, demi Tuhan, Pak. Kemalangan datang dari mulut. Hati-hati, agar Anda tidak harus menelan kata-kata itu.",
  ui_story_5048_50480201_84_dialog_content = "Hmm? Pak, warna di antara kedua mata Anda tampak aneh. Ini bisa menjadi pertanda buruk...",
  ui_story_5048_50480201_85_dialog_content = "Bagaimana kalau begini—saya akan memberikan ramalan gratis untukmu, dan kita akan melupakan apa yang terjadi di sini hari ini. Bagaimana menurutmu?",
  ui_story_5048_50480201_86_dialog_content = "Aku tidak percaya padamu sedetik pun!",
  ui_story_5048_50480201_87_dialog_content = "<color=#e8d9bb>Wuuss!!!</color>",
  ui_story_5048_50480201_88_dialog_content = "Hmm? Sepertinya kamu secara tidak sengaja mengambil dua lembaran untuk membentuk satu ramalan. Ini adalah...",
  ui_story_5048_50480201_89_dialog_content = "Kuda Yin dan Lembu Yin?!",
  ui_story_5048_50480201_90_dialog_content = "Seekor sapi mati menarik kuda kayu—keduanya tidak bisa maju. Pak, Anda harus berhati-hati!",
  ui_story_5048_50480201_91_dialog_content = "Bencana bisa terjadi kapan saja. Anda harus menghilangkan semua ancaman potensial segera dan tetap tenang!",
  ui_story_5048_50480201_92_dialog_content = "Emm...",
  ui_story_5048_50480201_93_dialog_content = "Ernest?",
  ui_story_5048_50480201_94_dialog_content = "Argh…",
  ui_story_5048_50480201_95_dialog_content = "Apa yang salah dengan kamu? Jika ada sesuatu yang ingin kamu katakan, katakan saja...",
  ui_story_5048_50480201_96_dialog_content = "Ini semua menjadi kenyataan cukup cepat...",
  ui_story_5048_50480201_97_dialog_content = "Arrrgh...",
  ui_story_5048_50480201_98_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5048_50480201_99_dialog_content = "<color=#e8d9bb>Seri klink dan gemerincing!</color>",
  ui_story_5048_50480201_100_dialog_content = "A-aku butuh bantuan di sini!",
  ui_story_5048_50480201_101_dialog_content = "Tolong!",
  ui_story_5048_50480201_102_dialog_content = "Bencana terjadi! Selamatkan nyawanya!",
  ui_story_5048_50480201_103_dialog_content = "Tolong! Seseorang, tolong aku!",
  ui_story_5048_50480201_104_dialog_content = "Tianxian, sedang apa kamu di sini?",
  ui_story_5048_50480201_105_dialog_content = "Nona Jiu? Putri Dantang? Memang tidak ada cerita tanpa kebetulan, tidak ada pertemuan tanpa takdir...",
  ui_story_5048_50480201_106_dialog_content = "Bos?!",
  ui_story_5048_50480201_107_dialog_content = "Bos, apa yang terjadi padamu? Ayo, bangun...",
  ui_story_5048_50480201_108_dialog_content = "Kulit pucat, mulut berbusa... Dahi merah menyala?",
  ui_story_5048_50480201_109_dialog_content = "Gejala-gejala ini... Bukankah ini keracunan <color=#FFB400>ravenflame</color>?",
  ui_story_5048_50480201_110_dialog_content = "Ravenflame adalah obat penghilang rasa sakit dengan sifat pemanasan, tetapi hanya bisa digunakan secara topikal, tidak untuk diminum!",
  ui_story_5048_50480201_111_dialog_content = "Jika tidak... Yah, kasus ringan keracunan ravenflame melibatkan muntah, diare, dan mati rasa di seluruh tubuh, sementara kasus parah ditandai dengan kesulitan bernapas, kejang, delirium, dan henti jantung.",
  ui_story_5048_50480201_112_dialog_content = "Sungguh pengkhianatan yang kejam...",
  ui_story_5048_50480201_113_dialog_content = "Jiu, tekan titik akupunktur fuquan-nya dan paksa dia untuk memuntahkan racunnya terlebih dahulu!",
  ui_story_5048_50480201_114_dialog_content = "Baik, Yang Mulia!",
  ui_story_5048_50480201_115_dialog_content = "Di mana dokter terdekat? Bisa ada yang menunjukkan jalan?",
  ui_story_5048_50480201_116_dialog_content = "Iya, iya! Lewat sini!",
  ui_story_5048_50480201_117_dialog_content = "Graagh!",
  ui_story_5048_50480201_118_dialog_content = "Apa?!",
  ui_story_5048_50480201_119_dialog_content = "Bergerak!",
  ui_story_5048_50480201_120_dialog_content = "Bagaimana Eclipsites bisa masuk ke Teluk Twin Pavilions?!",
  ui_story_5048_50480201_121_dialog_content = "Kamu bawa Ernest ke dokter dulu. Kami akan melindungimu.",
  ui_story_5048_50480201_122_dialog_content = "Ingat untuk memberi tahu dokter bahwa Ernest telah diracuni dengan ravenflame.",
  ui_story_5048_50480201_123_dialog_content = "O-Oke, aku akan!",
  ui_story_5048_50480201_124_dialog_content = "Yang Mulia, harap berhati-hati. Jangan terlalu memaksakan diri!",
  ui_story_5048_50480201_125_dialog_content = "Jiu, mungkin sudah terlalu lama sejak terakhir kali kamu melihat saya mengatasi Eclipsite.",
  ui_story_5048_50480302_1_dialog_content = "Yang Mulia, semua Eclipsite telah terhantam. Tidak ada satupun yang tersisa.",
  ui_story_5048_50480302_2_dialog_content = "Saya dengar tidak ada Eclipsite yang berkeliaran di Teluk Twin Pavilions, jadi bagaimana situasi saat ini bisa terjadi?",
  ui_story_5048_50480302_3_dialog_content = "Cukup aneh.",
  ui_story_5048_50480302_4_dialog_content = "Mari kembali ke restoran dan melihat-lihat.",
  ui_story_5048_50480302_5_dialog_content = "Pasti kamu! Selain kamu, siapa lagi yang bisa jadi pembunuhnya?",
  ui_story_5048_50480302_6_dialog_content = "Rekan-rekan sebangsa yang terkasih, saya menyarankan Anda untuk tidak menyebarkan tuduhan seperti itu dengan sembrono—hal itu mungkin merugikan keberuntungan Anda!",
  ui_story_5048_50480302_7_dialog_content = "Kami semua mendengarnya! Kamu yang menggunakan kata-kata kasar untuk menyerang Pak Ernest!",
  ui_story_5048_50480302_8_dialog_content = "Pak Ernest langsung pingsan setelah kamu selesai bicara!",
  ui_story_5048_50480302_9_dialog_content = "Oh, Tuhan tahu, menyebabkan bahaya pada orang lain hanya akan membawa konsekuensi negatif pada hidupku sendiri. Aku tak akan pernah melakukan hal seperti itu.",
  ui_story_5048_50480302_10_dialog_content = "Lalu bagaimana Anda tahu ini adalah pembunuhan yang direncanakan?",
  ui_story_5048_50480302_11_dialog_content = "Pasti kamu! Kamu pembunuhnya!",
  ui_story_5048_50480302_12_dialog_content = "Sebuah perasaan yang dianut oleh tentara bayaran seperti itu terlintas dalam pikiran—hidup dengan pedang, mati oleh pedang.",
  ui_story_5048_50480302_13_dialog_content = "Dia telah menjalani hidupnya dengan menipu orang lain, mengaburkan kebenaran... Kini, kebenaran tak bisa menyelamatkannya.",
  ui_story_5048_50480302_14_dialog_content = "Yang Mulia, Tianxian memang pandai membual, tetapi dia bukan orang yang berhati jahat.",
  ui_story_5048_50480302_15_dialog_content = "Jika memang dia dituduh secara salah, dia juga pantas untuk dikasihani.",
  ui_story_5048_50480302_16_dialog_content = "Kamu benar, kita tidak boleh hanya diam dan tidak mengangkat jari untuk membantu hanya karena tipu muslihat masa lalunya.",
  ui_story_5048_50480302_17_dialog_content = "Selain itu, tidak mudah bagi kami untuk bepergian sejauh ini di atas Shadowind. Jika salah satu dari kami dituduh dengan tuduhan seperti itu...",
  ui_story_5048_50480302_18_dialog_content = "Ini akan semakin sulit bagi kami untuk membangun kepercayaan dan bertukar informasi dengan orang yang bertanggung jawab di sini di masa depan.",
  ui_story_5048_50480302_19_dialog_content = "Kebijaksanaan Anda sangat mengagumkan, Yang Mulia.",
  ui_story_5048_50480302_20_dialog_content = "Kamu berhasil!",
  ui_story_5048_50480302_21_dialog_content = "Jangan ragu untuk menggerakkan mulut Anda, tetapi tolong, jaga tangan Anda!",
  ui_story_5048_50480302_22_dialog_content = "Tangkap dia! Jangan biarkan dia lolos!",
  ui_story_5048_50480302_23_dialog_content = "Mari kita tidak terbawa suasana, semuanya!",
  ui_story_5048_50480302_24_dialog_content = "Bukti yang meyakinkan sangat penting sebelum membuat tuduhan, apalagi sebelum menuntut hukuman. Li Tianxian mungkin memang tersangka utama di sini, tetapi bukti yang cukup harus ditemukan untuk menghukumnya.",
  ui_story_5048_50480302_25_dialog_content = "Lady, kamu memang benar, tapi bagaimana kita menemukan bukti?",
  ui_story_5048_50480302_26_dialog_content = "Bisakah Anda memberi tahu kami ke mana Ernest pergi dan apa yang dia lakukan hari ini?",
  ui_story_5048_50480302_27_dialog_content = "Bos kami memiliki rutinitas harian yang sangat teratur, dan hari ini pun tidak berbeda.",
  ui_story_5048_50480302_28_dialog_content = "Ini terutama mencakup memeriksa dapur dan terkadang mengamati umpan balik pelanggan di restoran.",
  ui_story_5048_50480302_29_dialog_content = "Jadi, apa yang dia makan hari ini?",
  ui_story_5048_50480302_30_dialog_content = "Dia tidak makan secara teratur karena setiap hidangan dari dapur menyediakan sampel cicipan khusus untuknya.",
  ui_story_5048_50480302_31_dialog_content = "Hidangan hanya dibawa ke meja pelanggan setelah mendapat persetujuan darinya.",
  ui_story_5048_50480302_32_dialog_content = "Selain ini, apakah kamu yakin bahwa dia sama sekali tidak memakan sesuatu yang lain?",
  ui_story_5048_50480302_33_dialog_content = "Tidak, aku bisa menjamin itu!",
  ui_story_5048_50480302_34_dialog_content = "Kalau begitu, racun seharusnya ada di makanan yang dicicipi Ernest.",
  ui_story_5048_50480302_35_dialog_content = "Racun?",
  ui_story_5048_50480302_36_dialog_content = "Benar. Alasan Ernest ambruk adalah karena racun ravenflame dalam tubuhnya.",
  ui_story_5048_50480302_37_dialog_content = "Li Tianxian, apakah kamu masuk ke dapur hari ini?",
  ui_story_5048_50480302_38_dialog_content = "Aku bersumpah pada Gulungan Kenaikan Ilahi—tidak!",
  ui_story_5048_50480302_39_dialog_content = "Apakah ada saksi yang dapat memberikan kesaksian mengenai hal ini?",
  ui_story_5048_50480302_40_dialog_content = "Pemberi kebaikan... Pak Victor!",
  ui_story_5048_50480302_41_dialog_content = "Saya mulai berbicara dengan orang yang menolong saya begitu saya melangkah masuk pintu. Dia bisa bersaksi untuk membela saya!",
  ui_story_5048_50480302_42_dialog_content = "Erm... Saya bisa bersaksi untuk ini.",
  ui_story_5048_50480302_43_dialog_content = "Apa yang terjadi... Apakah itu berarti dia tidak bersalah?",
  ui_story_5048_50480302_44_dialog_content = "... Jika bukan dia, lalu siapa yang melakukannya?",
  ui_story_5048_50480302_45_dialog_content = "Terima kasih banyak atas bantuan Anda, Tuan Putri Dantang. Tanpa campur tangan Anda, saya tidak akan bisa membersihkan diri dari kecurigaan ini jika saya melompat kembali ke laut dari tempat kami berasal.",
  ui_story_5048_50480302_46_dialog_content = "Jangan salah paham, aku tidak melakukannya untuk membantumu—aku hanya mencoba mencari kebenaran.",
  ui_story_5048_50480302_47_dialog_content = "Kalau bukan dia, lalu siapa lagi? Kita bahkan tidak tahu apakah Bos kita hidup atau mati. Apa yang harus kita lakukan sekarang?",
  ui_story_5048_50480302_48_dialog_content = "Jangan khawatir. Saya tidak akan menyerah karena sudah terlibat dalam masalah ini.",
  ui_story_5048_50480302_49_dialog_content = "Nona, tolong segel lokasi ini bersama rekan-rekan Anda dan jangan menyentuh satu debu pun. Selain itu, saya harus meminta Anda untuk menyusun daftar semua orang yang masuk dan keluar dari restoran hari ini.",
  ui_story_5048_50480302_50_dialog_content = "Oke, terima kasih... Ngomong-ngomong, bagaimana kami harus memanggil Anda?",
  ui_story_5048_50480302_51_dialog_content = "Panggil saja aku Dantang.",
  ui_story_5048_50480302_52_dialog_content = "Terima kasih, Nona Dantang!",
  ui_story_5048_50480302_53_dialog_content = "Putri Dantang, Anda benar-benar jiwa yang cantik dan baik hati, dan Anda menangani segala sesuatu dengan sangat tenang.",
  ui_story_5048_50480302_54_dialog_content = "Anda telah dibebaskan dari kecurigaan, namun Anda masih belum menghilang.",
  ui_story_5048_50480302_55_dialog_content = "Mungkin aku bukan pelakunya, tapi semua ini terjadi tepat di depan mataku. Aku tidak bisa hanya menjadi pengamat pasif.",
  ui_story_5048_50480302_56_dialog_content = "Apakah kamu memiliki ide tentang bagaimana kasus ini bisa diselesaikan?",
  ui_story_5048_50480302_57_dialog_content = "Dalam hal menyelesaikan kasus, keterampilan Anda lebih unggul daripada saya, jadi saya tentu saja tidak akan bermimpi untuk mencoba menginstruksikan Anda tentang cara menanganinya.",
  ui_story_5048_50480302_58_dialog_content = "Namun, saat dicakar oleh orang-orang tadi, aku sempat mendengar sesuatu yang menarik.",
  ui_story_5048_50480302_59_dialog_content = "Kata orang, pemilik restoran ini, Ernest, lahir dalam keluarga yang memiliki kekayaan luar biasa.",
  ui_story_5048_50480302_60_dialog_content = "Namun, untuk mewujudkan mimpinya menciptakan makanan kelas dunia, dia sampai membuka restoran di Twin Pavilions Bay.",
  ui_story_5048_50480302_61_dialog_content = "Dia menetapkan persyaratan yang sangat ketat untuk makanan yang disajikannya, dan jika restoran ini pernah menempati peringkat kedua di Teluk Twin Pavilions, tidak ada yang berani mengklaim tempat mereka berada di peringkat pertama.",
  ui_story_5048_50480302_62_dialog_content = "Siapa yang mungkin telah tersinggung oleh sosok terhormat seperti itu?",
  ui_story_5048_50480302_63_dialog_content = "Oh, mungkin daftarnya cukup panjang.",
  ui_story_5048_50480302_64_dialog_content = "Keterampilan memasak Ernest memang tak terbantahkan, tetapi dia adalah pria yang angkuh dan sombong jika memang ada.",
  ui_story_5048_50480302_65_dialog_content = "Dia sering memarahi murid-muridnya, selalu bertabrakan dengan para pengunjung, dan bahkan...",
  ui_story_5048_50480302_66_dialog_content = "Jika ada yang ingin kamu katakan, katakan saja. Ini bukan saatnya membuat teka-teki.",
  ui_story_5048_50480302_67_dialog_content = "Dia juga membuka kafe di atap di atas restoran.",
  ui_story_5048_50480302_68_dialog_content = "Bagi orang lokal di sini, berkumpul di kafe sama seperti pergi makan di Longzhou.",
  ui_story_5048_50480302_69_dialog_content = "Dan hal terpenting tentang makanan bukanlah makanannya itu sendiri...",
  ui_story_5048_50480302_70_dialog_content = "... Ini adalah hal-hal yang akan dibahas selama kita makan.",
  ui_story_5048_50480302_71_dialog_content = "Aku mengerti. Mungkin restoran ini adalah salah satu tempat pertemuan utama di mana pejabat setempat membahas urusan penting.",
  ui_story_5048_50480302_72_dialog_content = "Terima kasih atas masukannya, Master Li.",
  ui_story_5048_50480302_73_dialog_content = "Jadi, saat berguna, aku disebut Master Li, dan saat tidak, aku disebut pesulap bayaran... Yang Mulia, kemampuan manipulasi Anda bahkan lebih hebat daripada saya.",
  ui_story_5048_50480302_74_dialog_content = "Tianxian, jangan memaksakan keberuntunganmu.",
  ui_story_5048_50480302_75_dialog_content = "Jika masalah ini melibatkan pejabat lokal, tentu lebih rumit daripada yang telah kita duga sebelumnya.",
  ui_story_5048_50480302_76_dialog_content = "Yang Mulia, haruskah kita melepaskan diri dari kekacauan ini selagi kita masih bisa?",
  ui_story_5048_50480302_77_dialog_content = "Kita bisa menyerahkan kasus ini kepada perwakilan Umbraton Guild yang bermarkas di Twin Pavilions Bay, yang bekerja sama dengan keluarga Lin untuk menjaga ketertiban di sini.",
  ui_story_5048_50480302_78_dialog_content = "Tidak, itu tidak akan berhasil sama sekali!",
  ui_story_5048_50480302_79_dialog_content = "Yang Mulia belum mengungkapkan maksudnya. Apa yang sedang Anda omongkan?",
  ui_story_5048_50480302_80_dialog_content = "Saya baru saja melakukan ramalan untuk Anda, Yang Mulia...",
  ui_story_5048_50480302_81_dialog_content = "Jika Anda membiarkan masalah ini berkembang tanpa campur tangan Anda, pada akhirnya hal itu akan berdampak buruk pada Anda dan menimbulkan konsekuensi tak berujung!",
  ui_story_5048_50480302_82_dialog_content = "Yang Mulia sangat membenci ramalan. Berani-beraninya kau menyebut hal seperti itu di hadapannya?",
  ui_story_5048_50480302_83_dialog_content = "Sudahlah, Jiu.",
  ui_story_5048_50480302_84_dialog_content = "Masalah ini sudah sampai pada titik ini. Aku tidak bisa pergi begitu saja.",
  ui_story_5048_50480302_85_dialog_content = "Kita orang asing di negeri ini, jadi akan sulit bagi kita untuk mulai menyelidiki hubungan antarpersonal penduduk setempat.",
  ui_story_5048_50480302_86_dialog_content = "Tapi kita masih memiliki satu petunjuk untuk diikuti.",
  ui_story_5048_50480302_87_dialog_content = "Petunjuk apa?",
  ui_story_5048_50480302_88_dialog_content = "Herba, api raven.",
  ui_story_5048_50480401_1_dialog_content = "Permisi, bolehkah saya bertanya apakah Anda menjual herbal Longzhou di sini yang disebut ravenflame?",
  ui_story_5048_50480401_2_dialog_content = "Tidak, kami tidak punya itu.",
  ui_story_5048_50480401_3_dialog_content = "Tapi aku pernah mendengar orang-orang mengatakan bahwa di Twin Pavilions Bay, sebesar apapun itu, hanya toko kamu yang menjual ramuan ini.",
  ui_story_5048_50480401_4_dialog_content = "Kamu bisa membelinya dari siapa pun yang bilang itu. Kami tidak punya.",
  ui_story_5048_50480401_5_dialog_content = "Sikapmu sangat buruk... Aku ingin bicara dengan pemiliknya!",
  ui_story_5048_50480401_6_dialog_content = "Apa yang terjadi di sini? Katakan apa masalahnya, dan mari kita tetap bersahabat, ya?",
  ui_story_5048_50480401_7_dialog_content = "Nona Sheol, mereka di sini mencoba membuat masalah.",
  ui_story_5048_50480401_8_dialog_content = "Oh sayang... Berapa kali harus kubilang padamu?",
  ui_story_5048_50480401_9_dialog_content = "Siapa pun yang masuk ke toko ini adalah pelanggan, dan pelanggan adalah langit di atas, bumi di bawah, serta daging dari jantung kita yang berdetak.",
  ui_story_5048_50480401_10_dialog_content = "Bagaimana saya bisa mempercayaimu untuk mengurus cabang Twin Pavilions Bay jika kamu bersikap seperti ini?",
  ui_story_5048_50480401_11_dialog_content = "Tapi, Lady Sheol, bukankah kamu bilang bahwa ramuan itu hanya untuk—",
  ui_story_5048_50480401_12_dialog_content = "Ahem, bagaimana kalau kamu masuk ke belakang dan periksa persediaan barang dulu.",
  ui_story_5048_50480401_13_dialog_content = "Sayang, aku benar-benar minta maaf tentang itu. Asisten toko baru kami sepertinya belum begitu mengerti filosofi merek kami.",
  ui_story_5048_50480401_14_dialog_content = "Jika Anda merasa tersinggung, saya minta maaf. Izinkan saya menawarkan kompensasi atas keresahan Anda—semua orang diberi diskon dua belas persen saat berbelanja di sini hari ini!",
  ui_story_5048_50480401_15_dialog_content = "Kami hanya ingin membeli sebuah ramuan yang disebut ravenflame.",
  ui_story_5048_50480401_16_dialog_content = "Gadis Kecil...",
  ui_story_5048_50480401_17_dialog_content = "Sekali lihat kamu, sepertinya kau di sini bukan untuk membelinya, ya?",
  ui_story_5048_50480401_18_dialog_content = "Nona Sheol, tampaknya tidak ada yang luput dari perhatian Anda.",
  ui_story_5048_50480401_19_dialog_content = "Tapi kami tidak datang ke sini dengan niat membuat masalah. Kami sedang menyelidiki sebuah kasus.",
  ui_story_5048_50480401_20_dialog_content = "Apakah kamu sudah mendengar tentang insiden yang menimpa Pak Ernest sore ini?",
  ui_story_5048_50480401_21_dialog_content = "Ah, ya. Ernest terlibat dalam konflik antara faksi proteksionis dan perdagangan bebas di distrik barat Twin Pavilions Bay.",
  ui_story_5048_50480401_22_dialog_content = "Seperti ini memang pasti akan terjadi cepat atau lambat.",
  ui_story_5048_50480401_23_dialog_content = "Saya berharap Anda bisa membantu saya, Lady Sheol, dan memberi tahu apakah Anda ingat ada yang membeli ravenflame.",
  ui_story_5048_50480401_24_dialog_content = "Dengan cara itu, kita mungkin bisa menemukan pelaku sebenarnya dan mengamankan lingkungan bisnis yang stabil di Twin Pavilions Bay.",
  ui_story_5048_50480401_25_dialog_content = "Lingkungan bisnis lokal tidak akan stabil hanya dengan menyelesaikan kasus ini saja. Hal terakhir yang bisa dilakukan oleh seorang pengusaha seperti saya adalah membuat pelanggan saya kesal, jadi tolong jangan membuat situasi semakin sulit bagi saya.",
  ui_story_5048_50480401_26_dialog_content = "Wanita cantikku, aku khawatir kamu gagal mengenali siapa yang berdiri di hadapanmu.",
  ui_story_5048_50480401_27_dialog_content = "Anda berada di hadapan Putri Zhuohua dari Longzhou, Yang Mulia Dantang, utusan diplomatik negara yang ditunjuk oleh pihak atas.",
  ui_story_5048_50480401_28_dialog_content = "Jika kamu menyinggung perasaannya, kamu bisa melupakan penjualan ravenflame lagi. Bahkan, mungkin kamu akan merasa sulit untuk mendapatkan produk Longzhou di masa depan.",
  ui_story_5048_50480401_29_dialog_content = "Tapi jika saya memiliki stok dan tidak ada pelanggan, saya juga tidak akan bisa menjalankan bisnis.",
  ui_story_5048_50480401_30_dialog_content = "Kalau begitu, mungkin kami bisa menjadi pelanggan Anda, Nona Sheol?",
  ui_story_5048_50480401_30X1_dialog_content = "Nona kecil, itu akan menjadi suatu kehormatan. Selain ravenflame, kami juga memiliki berbagai macam produk lain yang lebih beragam daripada yang bisa Anda bayangkan.",
  ui_story_5048_50480401_30X2_dialog_content = "Berbagai macam produk, ya?",
  ui_story_5048_50480401_31_dialog_content = "Berdasarkan pemikiran ini, Anda bisa mengatakan informasi tentang orang yang membeli ravenflame mungkin dianggap sebagai barang yang dapat diperdagangkan di toko Anda?",
  ui_story_5048_50480401_32_dialog_content = "Hahaha! Barang dagangan ini agak rumit, tapi jika kamu benar-benar tulus dalam niatmu, aku tidak bisa hanya diam saja.",
  ui_story_5048_50480401_33_dialog_content = "Lady Sheol, tenang saja, selama harganya wajar, saya akan memberikan uangnya sekarang juga.",
  ui_story_5048_50480401_34_dialog_content = "Kalian Putri-putri Longzhou memang langsung pada intinya! Namun, harga dari barang ini bukanlah uang, melainkan seorang manusia.",
  ui_story_5048_50480401_35_dialog_content = "Seorang?",
  ui_story_5048_50480401_36_dialog_content = "Beberapa hari yang lalu, kerusuhan pecah di pasar tentara bayaran dekat Twin Pavilions Bay, yang menyebabkan saya kehilangan sejumlah besar barang.",
  ui_story_5048_50480401_37_dialog_content = "Tapi, tidak ada yang berani maju untuk mengambil tanggung jawab atas masalah ini.",
  ui_story_5048_50480401_38_dialog_content = "Yang saya punya hanyalah rumor bahwa seseorang misterius yang tidak dikenal muncul di tempat kejadian kerusuhan.",
  ui_story_5048_50480401_39_dialog_content = "Saya berharap ada seseorang yang bisa membantu saya menemukan orang misterius ini dan mengungkap kebenaran di balik kerusuhan.",
  ui_story_5048_50480401_40_dialog_content = "Apakah penjahat ini memiliki ciri khas yang membedakannya?",
  ui_story_5048_50480401_41_dialog_content = "Mereka bilang orang misterius itu menggunakan pedang berat, mengenakan jubah gelap, dan tertutup duri-duri yang sangat tajam.",
  ui_story_5048_50480401_42_dialog_content = "Wow, ini bukan orang biasa.",
  ui_story_5048_50480401_43_dialog_content = "Uh-huh. Apakah kamu mencari orang ini atau tidak, itu terserah kamu.",
  ui_story_5048_50480401_44_dialog_content = "Saya ada urusan sekarang, tapi silakan santai di toko sepuasnya. Jika butuh sesuatu, bilang saja ke pramuniaga dan saya akan mengingatkan mereka untuk memberi diskon untukmu!",
  ui_story_5048_50480401_45_dialog_content = "Terima kasih banyak, Nona Sheol.",
  ui_story_5048_50480401_46_dialog_content = "Oh, benar.",
  ui_story_5048_50480401_47_dialog_content = "Jika Anda menemukan orang misterius itu, pastikan untuk memperlakukan mereka dengan baik!",
  ui_story_5048_50480401_48_dialog_content = "Mengapa kita ingin memperlakukan penjahat seperti itu dengan baik? Lady Sheol ini terdengar seperti Tianxian... Aku harus mengakui, aku cukup bingung.",
  ui_story_5048_50480401_49_dialog_content = "Hal yang aku bicarakan adalah misteri alam, sesuatu yang memang sulit dipahami secara alami.",
  ui_story_5048_50480401_50_dialog_content = "Mengenai cara misterius Lady Sheol ini, saya tidak bisa memastikan apakah dia sengaja bersikap ambigu atau memang disengaja!",
  ui_story_5048_50480401_51_dialog_content = "Sengaja atau dengan sengaja... Bukankah mereka hal yang sama?",
  ui_story_5048_50480401_52_dialog_content = "Nah, pada dasarnya, sekarang tugas ini menjadi tanggung jawab Yang Mulia dan Nona Jiu untuk mencari orang misterius ini.",
  ui_story_5048_50480401_53_dialog_content = "Mungkin aku terampil dalam kecerdasan dan kata-kata, tetapi menguasai senjata adalah pekerjaan... yang lebih baik diserahkan kepada mereka yang lebih berpengalaman.",
  ui_story_5048_50480401_54_dialog_content = "Aku akan kembali ke restoran dan menunggu kabar baiknya!",
  ui_story_5048_50480401_55_dialog_content = "Jadi, bahkan Master Li juga memiliki momen ketakutannya.",
  ui_story_5048_50480401_56_dialog_content = "Seperti pepatah, orang bijak tahu batasannya dan memilih pertempurannya—hanya dengan begitu dia bisa menjadi pahlawan. Selain itu, saya juga tidak akan berdiam diri.",
  ui_story_5048_50480401_57_dialog_content = "Dalam menyelidiki rumor dan memastikan fakta situasi, saya masih punya beberapa trik yang bisa digunakan.",
  ui_story_5048_50480401_58_dialog_content = "Baiklah, mari kita berpencar dan maju, mungkin kita akan mencapai kemajuan lebih cepat. Terima kasih banyak, Master Li.",
  ui_story_5048_50480401_59_dialog_content = "Tentu saja.",
  ui_story_5048_50480401_60_dialog_content = "Yang Mulia, pasar tentara bayaran ada tepat di depan.",
  ui_story_5048_50480401_61_dialog_content = "Lebih besar dari yang saya perkirakan, tetapi itu tidak seharusnya menjadi masalah. Mari kita lakukan sebanyak mungkin penyelidikan dan mencari saksi dari peristiwa terbaru di sini.",
  ui_story_5048_50480401_62_dialog_content = "Ahh! Eclipsites ada di sini!",
  ui_story_5048_50480401_63_dialog_content = "Eclipsite lagi? Dan begitu cepat setelah serangan terakhir...",
  ui_story_5048_50480401_64_dialog_content = "Groar!",
  ui_story_5048_50480401_65_dialog_content = "Hati-hati, Yang Mulia!",
  ui_story_5048_50480401_66_dialog_content = "Ambil durinya!",
  ui_story_5048_50480401_67_dialog_content = "Yang Mulia, apakah Anda terluka?!",
  ui_story_5048_50480401_68_dialog_content = "Tidak. Tiba-tiba gadis itu mendekat kepadaku dan membantuku menghalau serangan Eclipsite barusan.",
  ui_story_5048_50480401_69_dialog_content = "Gadis itu...",
  ui_story_5048_50480401_70_dialog_content = "Mengayunkan pedang berat, mengenakan jubah, dan tertutup duri?",
  ui_story_5048_50480401_71_dialog_content = "Dia orang yang kita cari!",
  ui_story_5048_50480401_72_dialog_content = "Aku akan segera menangkapnya sekarang.",
  ui_story_5048_50480401_73_dialog_content = "Jiu, jangan gegabah.",
  ui_story_5048_50480401_74_dialog_content = "Mengapa tidak? Bukankah dia orang yang kita cari?",
  ui_story_5048_50480401_75_dialog_content = "Dia adalah orang yang kita cari, tapi lihat saja postur tegap dan ekspresi tegasnya...",
  ui_story_5048_50480401_76_dialog_content = "Sepertinya dia bukan orang yang sengaja melakukan perbuatan jahat.",
  ui_story_5048_50480401_77_dialog_content = "Hmm…",
  ui_story_5048_50480401_78_dialog_content = "Graagh!",
  ui_story_5048_50480401_79_dialog_content = "Biarkan ada cahaya!",
  ui_story_5048_50480401_80_dialog_content = "Dari cara dia mengejar Eclipsite ini dan melindungi orang yang lewat, saya yakin bisa diasumsikan bahwa dia adalah orang yang benar-benar baik hati.",
  ui_story_5048_50480401_81_dialog_content = "Apakah kamu ingat apa yang dikatakan oleh Lady Sheol?",
  ui_story_5048_50480401_82_dialog_content = "Jika Anda menemukan orang misterius itu, pastikan untuk memperlakukan mereka dengan baik!",
  ui_story_5048_50480401_83_dialog_content = "Dia mungkin bukan dalang di balik masalah baru-baru ini di sini, tetapi seseorang yang mengejar keadilan, seperti kita.",
  ui_story_5048_50480401_84_dialog_content = "Kalau begitu, aku akan membantunya.",
  ui_story_5048_50480401_85_dialog_content = "*Meraung*",
  ui_story_5048_50480401_86_dialog_content = "Hosh... hosh... hosh...",
  ui_story_5048_50480401_87_dialog_content = "Prajurit mulia, silakan istirahat sebentar—",
  ui_story_5048_50480401_88_dialog_content = "A-Apakah kamu juga di sini untuk menangkapku?",
  ui_story_5048_50480401_89_dialog_content = "Maaf telah membuat Anda kaget. Kami berasal dari benua Longzhou dan telah dipercayakan di tanah ini oleh Lady Sheol untuk menyelidiki penyebab kekacauan di pasar beberapa hari lalu.",
  ui_story_5048_50480401_90_dialog_content = "Bisakah kamu memberi tahu kami apa yang terjadi di sini?",
  ui_story_5048_50480401_91_dialog_content = "Nona Sheol...?",
  ui_story_5048_50480401_92_dialog_content = "Di-Di sini ada berbagai macam orang, bukan hanya tentara bayaran dan penjahat, tetapi juga...",
  ui_story_5048_50480401_93_dialog_content = "Graagh!!",
  ui_story_5048_50480401_94_dialog_content = "*Batuk*... Dan kita masih punya Eclipsite ini yang menerobos.",
  ui_story_5048_50480401_95_dialog_content = "Tempat seperti ini... akan menodai ujung pakaian seorang wanita bangsawan yang cantik.",
  ui_story_5048_50480401_96_dialog_content = "Saat tidak ada Eclipsites yang menyerang... manfaatkan kesempatan ini dan pulang secepat mungkin.",
  ui_story_5048_50480401_97_dialog_content = "Jika aku bisa membuktikan bahwa seorang wanita bangsawan bisa bertarung seperti tentara bayaran, apakah kamu akan berubah pikiran dan membantuku?",
  ui_story_5048_50480401_98_dialog_content = "Groar!",
  ui_story_5048_50480401_99_dialog_content = "... B-Baiklah! Kuserahkan ini padamu!",
  ui_story_5048_50480402_1_dialog_content = "Saya sudah selesai memeriksa—tidak ada satupun yang lolos dari pemeriksaan.",
  ui_story_5048_50480402_2_dialog_content = "Terima kasih sudah begitu mau membantu saya...",
  ui_story_5048_50480402_3_dialog_content = "Aku pikir penampilanku... mungkin menakutkanmu.",
  ui_story_5048_50480402_4_dialog_content = "Aku bisa melihat dengan jelas bahwa kamu sangat menawan dan menggemaskan. Kamu mengingatkanku pada adik perempuanku. Bagaimana mungkin kamu bisa menakutkanku?",
  ui_story_5048_50480402_5_dialog_content = "Duri-duri... ini... di tubuhku...",
  ui_story_5048_50480402_6_dialog_content = "Apakah mereka sakit?",
  ui_story_5048_50480402_7_dialog_content = "Aku... sudah terbiasa dengan mereka.",
  ui_story_5048_50480402_8_dialog_content = "Meskipun duri-duri ini menyebabkan rasa sakit, kamu juga bisa menggunakannya untuk berjuang dan membantu mereka yang membutuhkan...",
  ui_story_5048_50480402_9_dialog_content = "Penampilanmu sungguh mengagumkan!",
  ui_story_5048_50480402_10_dialog_content = "Oh...",
  ui_story_5048_50480402_11_dialog_content = "Aku Dantang, dan di sampingku ini adalah Jiu.",
  ui_story_5048_50480402_12_dialog_content = "Kami berasal dari Longzhou dan saat ini sedang menyelidiki sebuah kasus di sini.",
  ui_story_5048_50480402_13_dialog_content = "Lady Sheol mengatakan bahwa mungkin kamu tahu sesuatu, itulah sebabnya kami memberanikan diri datang ke sini untuk mencari kamu.",
  ui_story_5048_50480402_14_dialog_content = "Jadi... itu sebabnya kamu di sini.",
  ui_story_5048_50480402_15_dialog_content = "Bisakah kamu beritahu kami namamu sekarang?",
  ui_story_5048_50480402_16_dialog_content = "Areia...",
  ui_story_5048_50480402_17_dialog_content = "Nama saya Areia.",
  ui_story_5048_50480501_1_dialog_content = "Nona Areia, ketika Anda baru saja menyebutkan bahwa ada seseorang yang mengejar Anda, apakah Anda berkata jujur?",
  ui_story_5048_50480501_2_dialog_content = "Kamu bisa ceritakan kepada kami, jika tidak keberatan, tentu saja.",
  ui_story_5048_50480501_3_dialog_content = "Erm... J-Jangan menilai saya dari penampilan, sebenarnya aku ini tentara bayaran yang mengembara.",
  ui_story_5048_50480501_4_dialog_content = "Sejak lahir, aku harus hidup dengan penyakit yang mengerikan ini—duri hitam yang tumbuh di tubuhku.",
  ui_story_5048_50480501_5_dialog_content = "Jadi sekarang saya berkelana dari tempat ke tempat, berharap menemukan cara untuk menyembuhkan kondisi saya.",
  ui_story_5048_50480501_6_dialog_content = "Saya baru saja tiba di Twin Pavilions Bay beberapa waktu lalu.",
  ui_story_5048_50480501_7_dialog_content = "Saya bertemu dengan pemberi kerja berbayar tinggi di pasar tentara bayaran.",
  ui_story_5048_50480501_8_dialog_content = "Hei, lihat dirimu saja...",
  ui_story_5048_50480501_9_dialog_content = "Apakah kamu tahu trik yang bisa melukai tanpa meninggalkan bekas?",
  ui_story_5048_50480501_10_dialog_content = "A-Aku tidak tahu hal-hal seperti itu...",
  ui_story_5048_50480501_11_dialog_content = "Percayalah, pembayaran ini akan membuatmu bahagia.",
  ui_story_5048_50480501_12_dialog_content = "Aku tak akan pernah menyakiti siapa pun tanpa alasan yang baik...",
  ui_story_5048_50480501_13_dialog_content = "Cih, mencoba berlagak sok luhur dan benar di sini?",
  ui_story_5048_50480501_14_dialog_content = "Orang seperti kamu itu selusin sepeser pun; kamu tidak istimewa.",
  ui_story_5048_50480501_15_dialog_content = "Orang... menyukai... saya...?",
  ui_story_5048_50480501_16_dialog_content = "Saya pikir jika saya mengikutinya, saya bisa menemukan orang-orang yang menderita kondisi yang sama seperti saya, dan mungkin mereka bisa memberi tahu saya penyebab penyakit mengerikan ini.",
  ui_story_5048_50480501_17_dialog_content = "Tapi kemudian aku tahu... dia tidak kenal siapa pun yang mengerti tentang hal-hal ini.",
  ui_story_5048_50480501_18_dialog_content = "Faktanya, ternyata dia sebenarnya menemukan cara lain untuk menjalankan rencananya.",
  ui_story_5048_50480501_19_dialog_content = "Tapi Anda tidak menyerah pada pencarian hanya karena ini, bukan?",
  ui_story_5048_50480501_20_dialog_content = "Aku hanya tidak tahan berdiam diri... dan menyaksikan orang-orang terluka, jadi aku terus mencari sendiri.",
  ui_story_5048_50480501_21_dialog_content = "Tapi aku terlalu ceroboh... Aku terbongkar di pasar beberapa hari yang lalu.",
  ui_story_5048_50480501_22_dialog_content = "Masalah di pasar malam sebenarnya adalah akibat dia menangkap saya.",
  ui_story_5048_50480501_23_dialog_content = "Jadi para Eclipsite itu sebenarnya dibawa ke sini oleh majikan tersebut?",
  ui_story_5048_50480501_24_dialog_content = "Aku benar-benar minta maaf... Ini semua salahku!",
  ui_story_5048_50480501_25_dialog_content = "Jadi, aku tidak bisa menyerah begitu saja dan membiarkan rencananya berhasil.",
  ui_story_5048_50480501_26_dialog_content = "Sepertinya hak dan salah di sini tidak lebih sedikit daripada di Longzhou.",
  ui_story_5048_50480501_27_dialog_content = "Cara dunia adalah mencari keuntungan pribadi.",
  ui_story_5048_50480501_28_dialog_content = "Dengan begitu banyak uang yang mengalir masuk dan keluar dari saluran perdagangan Twin Pavilions Bay, bagaimana mungkin tempat ini tidak menarik baik kebaikan maupun kejahatan?",
  ui_story_5048_50480501_29_dialog_content = "Tapi kita baru saja tiba. Kenapa kita sudah menghadapi begitu banyak kejadian aneh?",
  ui_story_5048_50480501_30_dialog_content = "...Kamu mengangkat poin yang bagus, Jiu. Mungkin ini bukan kejadian yang terisolasi. Mungkin ada hubungan tersembunyi di antara mereka...",
  ui_story_5048_50480501_31_dialog_content = "Areia, apakah kamu menemukan informasi berguna selama penyelidikanmu?",
  ui_story_5048_50480501_32_dialog_content = "Hmm... Pemberi kerja yang saya sebutkan adalah kepala kelompok perdagangan di distrik barat Twin Pavilions Bay.",
  ui_story_5048_50480501_33_dialog_content = "Dia adalah anggota dari kelompok yang disebut fraksi perdagangan bebas oleh penduduk setempat dan memiliki kebencian yang kuat terhadap para proteksionis...",
  ui_story_5048_50480501_34_dialog_content = "Jadi, targetnya adalah seseorang dari faksi proteksionis.",
  ui_story_5048_50480501_35_dialog_content = "Semua hal saling terhubung.",
  ui_story_5048_50480501_36_dialog_content = "Saya ingat Lady Sheol menyebutkan bahwa Ernest terlibat dalam konflik antara faksi proteksionis dan perdagangan bebas.",
  ui_story_5048_50480501_37_dialog_content = "Sebenarnya... Aku menemukan identitas target selama penyelidikanku... Aku ingin menangani Eclipsite dan pergi mencari seorang pria bernama Victor.",
  ui_story_5048_50480501_38_dialog_content = "Apa katamu?",
  ui_story_5048_50480501_39_dialog_content = "Targetnya adalah... Pak Victor, perwakilan Umbraton Guild yang ditugaskan di Twin Pavilions Bay.",
  ui_story_5048_50480501_40_dialog_content = "Oh, tidak...",
  ui_story_5048_50480501_41_dialog_content = "Victor adalah nama dari orang yang memberi manfaat kepada Tianxian!",
  ui_story_5048_50480501_42_dialog_content = "A-Achoo!",
  ui_story_5048_50480501_43_dialog_content = "Master Li, kau baik-baik saja?",
  ui_story_5048_50480501_44_dialog_content = "Bukan apa-apa, silakan, lanjutkan.",
  ui_story_5048_50480501_45_dialog_content = "... Jadi tentu saja aku merasa sangat terganggu, karena Ernest adalah temanku dan satu-satunya orang yang mendorongku untuk lebih tegas.",
  ui_story_5048_50480501_46_dialog_content = "Meskipun dia memiliki lidah yang tajam, dan kadang-kadang saya membalas dengan beberapa kritik sendiri, saya tahu bahwa sudut pandangnya sebenarnya biasanya sangat masuk akal.",
  ui_story_5048_50480501_47_dialog_content = "Dia mungkin belum menyadari ini, tapi aku sudah mulai mendorong praktik-praktik para proteksionis, dengan tujuan agar mereka dikenal oleh semua orang.",
  ui_story_5048_50480501_48_dialog_content = "Tetapi sekarang, jika dia benar-benar selesai, para pelindung akan kehilangan juara paling berpengaruh mereka...",
  ui_story_5048_50480501_49_dialog_content = "Mungkin saya harus mempertimbangkan kembali pilihan saya untuk mendukung para proteksionis.",
  ui_story_5048_50480501_50_dialog_content = "Sebagai perwakilan Umbraton Guild untuk Twin Pavilions Bay, Bapak Victor selalu dikenal dengan sikap tidak ikut campur terhadap kelompok-kelompok perdagangan.",
  ui_story_5048_50480501_51_dialog_content = "Namun baru-baru ini, dia memutuskan untuk tidak mengabaikannya.",
  ui_story_5048_50480501_52_dialog_content = "Dia juga berencana untuk mempromosikan usulan para proteksionis, sehingga membuat dirinya menjadi target para pedagang bebas.",
  ui_story_5048_50480501_53_dialog_content = "Tapi Tuan Victor bukanlah korban dari komplotan tadi. Sebaliknya, pemilik restoran, Ernest, yang diracuni dan jatuh pingsan.",
  ui_story_5048_50480501_54_dialog_content = "Apakah pedagang bebas itu memiliki dua sasaran?",
  ui_story_5048_50480501_55_dialog_content = "Jiu, kamu ingat bagaimana Ernest mencicipi semua makanan yang keluar dari dapur?",
  ui_story_5048_50480501_56_dialog_content = "Pelayan restoran memang menyebutkan fakta ini.",
  ui_story_5048_50480501_57_dialog_content = "Tuan Victor tidak sempat makan karena Tianxian sedang meramal untuknya.",
  ui_story_5048_50480501_58_dialog_content = "... Pembunuh itu mengutak-atik makanan Victor.",
  ui_story_5048_50480501_59_dialog_content = "Ernest keracunan karena mencicipi hidangan Victor dan malah menjadi korban alih-alih sasaran yang dimaksud!",
  ui_story_5048_50480501_60_dialog_content = "Jika calon pembunuh ini tahu sebelumnya bahwa Ernest, seorang pelindung, memiliki kebiasaan mencicipi makanan sebelum menyajikannya...",
  ui_story_5048_50480501_61_dialog_content = "Menggunakan racun akan menjadi strategi yang sempurna untuk sekali dayung, dua pulau terlampaui.",
  ui_story_5048_50480501_62_dialog_content = "Jadi ternyata Tianxian kadang-kadang bisa menyelamatkan nyawa juga.",
  ui_story_5048_50480501_63_dialog_content = "Ngomong-ngomong, Nona Areia... apakah Anda baru saja mengatakan bahwa pelakunya telah kembali ke pasar tentara bayaran?",
  ui_story_5048_50480501_64_dialog_content = "Erm... dia masih mencari seseorang untuk membantunya menyingkirkan Victor.",
  ui_story_5048_50480501_65_dialog_content = "Apakah konspirasi terhadap Victor masih berlanjut?",
  ui_story_5048_50480501_66_dialog_content = "Tolong! Tolong!",
  ui_story_5048_50480501_67_dialog_content = "Di ambang kematian!",
  ui_story_5048_50480501_68_dialog_content = "Groar!",
  ui_story_5048_50480501_69_dialog_content = "Tidakkah kamu bilang aku akan bertemu dengan seseorang yang saleh yang akan mengubah kesialan menjadi berkah?",
  ui_story_5048_50480501_70_dialog_content = "Yang bisa saya lihat di sini hanya Eclipsites! Di mana penyelamat baik hati saya?!",
  ui_story_5048_50480501_71_dialog_content = "Ah, aku juga tak menyangka situasinya akan begini. Orang baik yang ditakdirkan untuk menyelamatkan hidupmu bukanlah bangsawan Lumopolis, dan bukan juga Tuan Putri Longzhou...",
  ui_story_5048_50480501_72_dialog_content = "Itu aku, peramal yang tidak tahu malu. Aku sangat minta maaf!",
  ui_story_5048_50480601_1_dialog_content = "Pak Victor!",
  ui_story_5048_50480601_2_dialog_content = "Kakak Dantang!",
  ui_story_5048_50480601_3_dialog_content = "Apa kamu baik-baik saja? Kamu tidak terluka sama sekali?",
  ui_story_5048_50480601_4_dialog_content = "Aku baik-baik saja, aku tidak terluka...",
  ui_story_5048_50480601_5_dialog_content = "Dan di mana Tianxian?",
  ui_story_5048_50480601_6_dialog_content = "Master Li menggiring semua Eclipsite sendirian demi menyelamatkanku...",
  ui_story_5048_50480601_7_dialog_content = "Tolong selamatkan dia sebelum terlambat!",
  ui_story_5048_50480601_8_dialog_content = "Mengapa dia tidak bisa memprediksi bahwa hari ini dia akan berhadapan langsung dengan bencana?",
  ui_story_5048_50480601_9_dialog_content = "Senang melihat kamu akhirnya bisa bercanda, tapi ini bukan saatnya.",
  ui_story_5048_50480601_10_dialog_content = "Maaf, Yang Mulia. Saya khawatir dia mungkin baru saja mempertaruhkan hidupnya dalam upaya untuk menunjukkan keberaniannya.",
  ui_story_5048_50480601_11_dialog_content = "... Ayo, mari kita lihat!",
  ui_story_5048_50480601_12_dialog_content = "Jiu, lihat!",
  ui_story_5048_50480601_13_dialog_content = "Groar! Groar!!!",
  ui_story_5048_50480601_14_dialog_content = "Kenapa Eclipsite-Eclipsite ini berkerumun dan mengaum ke tanah?",
  ui_story_5048_50480601_15_dialog_content = "Sepertinya mereka sedang mengelilingi seseorang... Tunggu, apa mungkin...",
  ui_story_5048_50480601_16_dialog_content = "Graaagh!",
  ui_story_5048_50480601_17_dialog_content = "Mereka melihat kita!",
  ui_story_5048_50480601_18_dialog_content = "Maka ayo kita habisi mereka dengan cepat!",
  ui_story_5048_50480602_1_dialog_content = "Tianxian...",
  ui_story_5048_50480602_2_dialog_content = "Aneh, dia tidak ada di sini?",
  ui_story_5048_50480602_3_dialog_content = "Hmm?",
  ui_story_5048_50480602_4_dialog_content = "Heheheh…",
  ui_story_5048_50480602_5_dialog_content = "Jiu, lihat lagi. Apa yang tadi dikelilingi oleh Eclipsites?",
  ui_story_5048_50480602_6_dialog_content = "Tutup lubang saluran yang mengarah ke selokan bawah tanah...",
  ui_story_5048_50480602_7_dialog_content = "Apakah ada patung gula yang tersangkut di dalamnya?",
  ui_story_5048_50480602_8_dialog_content = "Sepertinya dia sudah berhasil kabur dengan liciknya, jadi kita tidak perlu khawatir lagi.",
  ui_story_5048_50480602_9_dialog_content = "Kakak Dantang!",
  ui_story_5048_50480602_10_dialog_content = "Areia?",
  ui_story_5048_50480602_11_dialog_content = "Apa situasinya? Apakah Lady Sheol sudah diberi tahu tentang apa yang sedang terjadi?",
  ui_story_5048_50480602_12_dialog_content = "Ya! Juga...",
  ui_story_5048_50480602_13_dialog_content = "Juga, aku membawa Guild bersama.",
  ui_story_5048_50480602_14_dialog_content = "Nona Sheol...",
  ui_story_5048_50480602_15_dialog_content = "Akhirnya kita bertemu lagi, Nona kecil.",
  ui_story_5048_50480602_16_dialog_content = "Terima kasih banyak, Lady Sheol, atas kehadiranmu yang tepat waktu. Sekarang kita semua di sini, mari kita segera menangkap pelakunya.",
  ui_story_5048_50480602_17_dialog_content = "Jangan khawatir tentang itu. Karena kamu telah membantu kami menemukan saksi kunci...",
  ui_story_5048_50480602_18_dialog_content = "Guild Umbraton, bekerja sama dengan organisasi seperti Lin Guild dan Serikat Kurir, dengan cepat menangkap pelakunya.",
  ui_story_5048_50480602_19_dialog_content = "Seperti yang Anda duga, dia juga mengakui sebagai orang yang merencanakan kekacauan Eclipsite akhir-akhir ini.",
  ui_story_5048_50480602_20_dialog_content = "Sekarang, atas nama serikat kami, kami dengan khidmat mengucapkan terima kasih kepada Anda, Utusan Longzhou, Putri Dantang, atas bantuan yang sangat berharga.",
  ui_story_5048_50480602_21_dialog_content = "Terima kasih, Putri Dantang, karena telah membantu kami mengungkap para pelaku kejahatan!",
  ui_story_5048_50480602_22_dialog_content = "Terima kasih, Putri Dantang! Terima kasih, Putri Dantang!",
  ui_story_5048_50480602_23_dialog_content = "Saya merasa Lady Sheol tahu siapa pelakunya sejak awal... tapi dia ingin menangkapnya atas nama kita.",
  ui_story_5048_50480602_24_dialog_content = "Twin Pavilions Bay awalnya terbagi menjadi dua bagian, dan dikuasai oleh Umbraton Guild dan Lin Guild.",
  ui_story_5048_50480602_25_dialog_content = "Kepentingan mereka yang saling bertentangan begitu terkait, saya khawatir mereka sendiri tidak mampu menyelesaikan masalah tersebut.",
  ui_story_5048_50480602_26_dialog_content = "Kami, sebagai orang luar, berhasil menangkap pelakunya dan dengan demikian menjadi perisai bagi mereka.",
  ui_story_5048_50480602_27_dialog_content = "Jadi, kita sedang dimanfaatkan?",
  ui_story_5048_50480602_28_dialog_content = "Manfaat yang timbul dari resolusi ini tidak sepihak—resolusi ini juga telah membantu kita.",
  ui_story_5048_50480602_29_dialog_content = "Kami sekarang telah membangun reputasi kami, tidak lama setelah tiba di Twin Pavilions Bay. Hal-hal akan menjadi lebih mudah bagi kami di masa depan.",
  ui_story_5048_50480602_30_dialog_content = "Gadis-gadis kecil, sudahkah kalian selesai berbisik-bisik di sana?",
  ui_story_5048_50480602_31_dialog_content = "Jika ada hal yang membuat Anda tidak puas, jangan ragu untuk memberi tahu saya. Perwakilan guild semua ada di sini dan pasti akan membantu Anda menyelesaikan masalah apa pun yang mungkin Anda miliki.",
  ui_story_5048_50480602_32_dialog_content = "Kamu sudah melakukan banyak hal, Nona Sheol, dan semua orang.",
  ui_story_5048_50480602_33_dialog_content = "Saya hanya bertanya-tanya, bagaimana kita akan menangani perselisihan antara pedagang bebas dan proteksionis di Twin Pavilions Bay di masa depan?",
  ui_story_5048_50480602_34_dialog_content = "Aku banyak berpikir tentang itu hari ini, dan akhirnya aku bisa memahami sesuatu.",
  ui_story_5048_50480602_35_dialog_content = "Kita semua sepakat bahwa Twin Pavilions Bay memerlukan sistem yang adil dan kontrol yang sesuai.",
  ui_story_5048_50480602_36_dialog_content = "Terlepas dari apakah dukungan dari faksi perdagangan lain ada di masa depan, saya akan terus mempromosikan usulan dari para proteksionis.",
  ui_story_5048_50480602_37_dialog_content = "Meskipun hal ini memberikan batasan tertentu pada kegiatan dan kepentingan faksi-faksi lain yang ada.",
  ui_story_5048_50480602_38_dialog_content = "Batasan...",
  ui_story_5048_50480602_39_dialog_content = "<color=#e8d9bb>Cuit, cuit, teriak—</color>",
  ui_story_5048_50480602_39X1_dialog_content = "<color=#e8d9bb>Sheol menatap langit dengan ekspresi penuh pikiran.</color>",
  ui_story_5048_50480602_40_dialog_content = "Semua kendala ini akan menghasilkan manfaat yang jauh lebih besar.",
  ui_story_5048_50480602_41_dialog_content = "Bagaimana menurutmu, Gadis Kecil?",
  ui_story_5048_50480602_42_dialog_content = "Hmm, saya tidak keberatan.",
  ui_story_5048_50480602_43_dialog_content = "Nah, memiliki dukungan dari Putri Longzhou membuat saya merasa lebih tenang.",
  ui_story_5048_50480602_44_dialog_content = "Tapi, apa kamu tidak takut di masa depan harus menghadapi upaya pencemaran nama baik dari faksi oposisi?",
  ui_story_5048_50480602_45_dialog_content = "Takut... Tentu saja aku takut.",
  ui_story_5048_50480602_46_dialog_content = "Mungkin saya harus mempertimbangkan untuk menyewa seorang pengawal seperti kamu.",
  ui_story_5048_50480602_47_dialog_content = "Tapi seperti yang dikatakan oleh Master Li, saya terlahir di bawah bintang keberuntungan, dan selalu bisa mengandalkan bantuan dari para dermawan yang saleh untuk mengubah kemalangan menjadi berkah...",
  ui_story_5048_50480602_48_dialog_content = "Hei, kenapa tidak minta Master Li untuk menjadi pengawal ku?",
  ui_story_5048_50480602_49_dialog_content = "Ahem, saya menyarankan Anda untuk mempertimbangkan kembali.",
  ui_story_5048_50480602_50_dialog_content = "A-Achoo!",
  ui_story_5048_50480602_51_dialog_content = "Mengingat banyaknya bersin, pasti banyak orang yang memikirkan saya hari ini... tapi kenapa belum ada yang datang kepadaku untuk meramal?",
  ui_story_5048_50480602_52_dialog_content = "<color=#e8d9bb>Ciprat, ciprat</color>",
  ui_story_5048_50480602_53_dialog_content = "Putri Ye, Pangeran Ji... Insiden Keluarga Lin, Shadowind?",
  ui_story_5048_50480602_54_dialog_content = "Cih, aku perlu memikirkan ini dengan cermat.",
  ui_story_5048_50480602_55_dialog_content = "<color=#e8d9bb>Wuuuuuus!</color>",
  ui_story_5048_50480602_56_dialog_content = "Ular Yang di atas, Banteng Yin di bawah. Musim Semi melahirkan Banteng dan Ular, bersiap untuk kekacauan empat musim. Apakah mungkin Longzhou...",
  ui_story_5048_50480602_57_dialog_content = "Tidak, itu pasti salah. Mungkin aku terlalu lelah untuk melakukan ramalan sekarang... benar, kan?",
  ui_story_5048_50480602_58_dialog_content = "Ini dia! Ini dia!",
  ui_story_5048_50480602_59_dialog_content = "Makan sendiri! Makan sendiri!",
  ui_story_5048_50480602_60_dialog_content = "Apa yang kamu bicarakan? Aku belum makan apa-apa, aku hanya menunggu kalian berdua.",
  ui_story_5048_50480602_61_dialog_content = "Terbakar habis! Terbakar habis!",
  ui_story_5048_50480602_62_dialog_content = "Temukan Dantang! Temukan Dantang!",
  ui_story_5048_50480602_63_dialog_content = "Jaga paruh kecilmu! Ingat untuk memanggilnya Tuan Putri Dantang saat kamu pergi keluar!",
  ui_story_5048_50480602_64_dialog_content = "Putri?",
  ui_story_5048_50480602_65_dialog_content = "Putri?",
  ui_story_5048_50480602_66_dialog_content = "Heh, hal seperti ini bukan pilihan.",
  ui_story_5048_50480602_67_dialog_content = "Seperti yang telah disebutkan oleh Lin Guild sebelumnya, saya adalah Dantang, Utusan Kerajaan Ji Longzhou.",
  ui_story_5048_50480602_68_dialog_content = "Saya berdiri di sini hari ini, mewakili sumber daya dan niat baik yang dapat disediakan dari seberang laut.",
  ui_story_5048_50480602_69_dialog_content = "Kami berharap bahwa rute perdagangan lintas samudra ini tidak hanya dapat memperkuat komunikasi dengan guild-guild di Umbraton...",
  ui_story_5048_50480602_70_dialog_content = "Namun, itu juga dapat mencapai Lumopolis, Federasi Illumina, dan bahkan daerah terpencil di Northland.",
  ui_story_5048_50480602_71_dialog_content = "...",
  ui_story_5048_50480602_72_dialog_content = "Tentu saja, budaya dan barang-barang dari Astra juga dapat masuk ke benua Longzhou yang lebih luas melalui jalur perdagangan ini.",
  ui_story_5048_50480602_72X1_dialog_content = "Peralatan dan sumber daya unik dari Astra mungkin juga dapat membantu Longzhou mengatasi ancaman di garis pantai...",
  ui_story_5048_50480602_73_dialog_content = "Singkatnya, ini adalah saluran perdagangan yang dapat menghubungkan dua benua!",
  ui_story_5048_50480602_74_dialog_content = "Hadirin sekalian, ini bukan hanya mimpi, tetapi kenyataan yang dapat kita raih.",
  ui_story_5048_50480602_75_dialog_content = "Para pengguna awal dapat memanfaatkan kesempatan ini untuk memulai perjalanan yang ditakdirkan melintasi zaman.",
  ui_story_5048_50480602_76_dialog_content = "Dengan keberadaannya, perjuangan kita melawan makhluk-makhluk kegelapan itu juga akan membuka lebih banyak peluang.",
  ui_story_5048_50480602_77_dialog_content = "Baiklah!",
  ui_story_5048_50480602_78_dialog_content = "Baik. Sudah lama saya tidak mendengar kata-kata penuh harapan seperti itu.",
  ui_story_5048_50480602_79_dialog_content = "Shadowlord... Shadowlord juga ada di sini!",
  ui_story_5048_50480602_80_dialog_content = "Penguasa Umbraton, Lord Istvan!",
  ui_story_5048_50480602_81_dialog_content = "Dengan senang hati saya menerima keberanian dan ketulusan Anda, atas nama organisasi saya.",
  ui_story_5048_50480602_82_dialog_content = "Mari kita lihat apakah hasil kerjasama kita benar-benar dapat membawa masa depan bagi kedua benua kita.",
  ui_story_5048_50480602_83_dialog_content = "Kupikir itu setidaknya bisa menjadi awal yang baik.",
  ui_story_5048_50480602_84_dialog_content = "Sebuah awal yang baik untuk era baru.",
  ui_story_5048_50480602_85_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_5048_50480602_86_dialog_content = "Angin naik.",
  ui_story_5048_50480602_87_dialog_content = "Hujan lembut membasahi Twin Pavilions Bay...",
  ui_story_5048_50480602_88_dialog_content = "Segera datang.",
  ui_story_5048_50480701_1_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian...</color>",
  ui_story_5048_50480701_2_dialog_content = "Yang Mulia, jalur gunung ini penuh bahaya, tolong berhati-hati!",
  ui_story_5048_50480701_3_dialog_content = "Ramuan terbaik sering tumbuh di tempat yang paling berbahaya.",
  ui_story_5048_50480701_4_dialog_content = "Saat saya masih muda, seluruh keluarga saya tertular wabah dan pergi ke puncak gunung yang paling berbahaya untuk mengumpulkan ramuan.",
  ui_story_5048_50480701_5_dialog_content = "Medan saat ini, dengan bukit-bukit kecilnya, sama sekali tidak menjadi masalah.",
  ui_story_5048_50480701_6_dialog_content = "Astaga... Yang Mulia, mungkin Anda tidak lelah, tapi Anda telah membuat kami semua kelelahan.",
  ui_story_5048_50480701_7_dialog_content = "Pemilik restoran itu, Ernest, sudah sembuh.",
  ui_story_5048_50480701_8_dialog_content = "Mengapa kita masih mencari jamu untuknya?",
  ui_story_5048_50480701_9_dialog_content = "Meskipun hidupnya tidak lagi dalam bahaya besar, kesehatannya pasti terpengaruh parah.",
  ui_story_5048_50480701_10_dialog_content = "Saat ini, hanya pilihan herbal yang sangat spesifik yang dapat dengan cepat memberi nutrisi pada tubuh dan pikirannya untuk menggantikan kekurangan yang masih ada dalam kondisi tubuhnya.",
  ui_story_5048_50480701_11_dialog_content = "Bapak Ernest dan saya saling menghargai kelebihan satu sama lain. Persahabatan seperti ini sangat langka, dan saya sangat menghargai ikatan ini.",
  ui_story_5048_50480701_12_dialog_content = "Jadi tentu saja aku harus menunjukkan rasa terima kasihku segera dan membiarkan dia mencoba tonik tradisional Longzhou.",
  ui_story_5048_50480701_13_dialog_content = "Ini juga bisa dianggap sebagai kisah yang banyak diceritakan dalam sejarah pertukaran kuliner antara Astra dan Longzhou.",
  ui_story_5048_50480701_14_dialog_content = "Tapi apakah benar herbal Longzhou bisa ditemukan di tempat ini?",
  ui_story_5048_50480701_15_dialog_content = "Saya sudah mengkonfirmasi ini dengan penduduk setempat.",
  ui_story_5048_50480701_16_dialog_content = "Tempat ini tidak memiliki ramuan kami, tetapi ada jenis yang berguna yang dikenal sebagai buah wolfberry merah, yang selama ini mereka anggap hanya sebagai rumput liar.",
  ui_story_5048_50480701_17_dialog_content = "Beberapa hari yang lalu hujan turun cukup lebat, jadi sekarang setelah langit cerah, ini adalah waktu yang sempurna bagi buah wolfberry merah untuk berkembang.",
  ui_story_5048_50480701_18_dialog_content = "Buah merah di depan!",
  ui_story_5048_50480701_19_dialog_content = "Enak! Ini enak sekali!",
  ui_story_5048_50480701_20_dialog_content = "Mengingat kalian berdua tampaknya sangat ahli dalam mencari makan di alam liar, mulai sekarang kalian bisa berhenti memintaku melon dan kurma setiap hari.",
  ui_story_5048_50480701_21_dialog_content = "Tunggu, buah yang dimakan Squawk dan Jabber...",
  ui_story_5048_50480701_22_dialog_content = "Ini adalah buah goji merah!",
  ui_story_5048_50480701_23_dialog_content = "Kami menemukannya! Kami benar-benar menemukannya!",
  ui_story_5048_50480701_24_dialog_content = "Oh, jadi buah merah kecil ini adalah obat herbal?",
  ui_story_5048_50480701_25_dialog_content = "Tianxian, jangan makan terlalu banyak mentah-mentah seperti itu, mereka cepat meningkatkan api dalam tubuh dan menyebabkan diare.",
  ui_story_5048_50480701_26_dialog_content = "Nona Jiu, seharusnya kamu bilang sesuatu dari tadi...",
  ui_story_5048_50480701_27_dialog_content = "Mengomel, Mengoceh, kalian dengar itu? Makan terlalu banyak dan kalian hanya akan menyalahkan diri sendiri atas akibatnya...",
  ui_story_5048_50480701_28_dialog_content = "Cukup bermain-main—ingat untuk memetik sebanyak mungkin dan mengisi keranjangmu!",
  ui_story_5048_50480701_29_dialog_content = "Ya, Tuan Putri!",
  ui_story_5048_50480701_30_dialog_content = "Tentu saja.",
  ui_story_5048_50480701_31_dialog_content = "Saudari-saudari, aku penasaran apa yang sedang kalian berdua lakukan sekarang...",
